# Custom Type Guards with Type Predicates (`is`) 🛡️

Create custom functions that narrow types using the `arg is Type` return syntax:

```typescript
interface AdminUser {
  name: string;
  adminPrivileges: string[];
}

function isAdmin(user: any): user is AdminUser {
  return typeof user === "object" && user !== null && "adminPrivileges" in user;
}

const candidate: unknown = { name: "Alice", adminPrivileges: ["root"] };

if (isAdmin(candidate)) {
  // candidate is narrowed to AdminUser!
  console.log("Admin privileges:", candidate.adminPrivileges);
}
```

