# Real-World: Type-Safe State Machine 🚦

```typescript
type Action =
  | { type: "FETCH_START" }
  | { type: "FETCH_SUCCESS"; payload: string[] }
  | { type: "FETCH_ERROR"; error: string };

type State = {
  loading: boolean;
  data: string[];
  error: string | null;
};

function stateReducer(state: State, action: Action): State {
  switch (action.type) {
    case "FETCH_START":
      return { ...state, loading: true, error: null };
    case "FETCH_SUCCESS":
      return { loading: false, data: action.payload, error: null };
    case "FETCH_ERROR":
      return { loading: false, data: [], error: action.error };
  }
}

let state: State = { loading: false, data: [], error: null };
state = stateReducer(state, { type: "FETCH_START" });
state = stateReducer(state, { type: "FETCH_SUCCESS", payload: ["Item A", "Item B"] });
console.log("Final State:", state);
```

